-- TOZRA SOCIAL ADVANCED V2
-- Run in the EXISTING TOZRA Supabase project after:
-- TOZRA_COMMUNITY.sql and TOZRA_SOCIAL_ADVANCED.sql

-- Reels metadata and cover frame generated by the browser-side composer.
alter table public.community_posts
  add column if not exists post_format text not null default 'post',
  add column if not exists cover_path text,
  add column if not exists audio_label text;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'community_posts_post_format_check') then
    alter table public.community_posts add constraint community_posts_post_format_check
      check (post_format in ('post','reel'));
  end if;
end $$;
create index if not exists community_posts_reels_created_idx
  on public.community_posts(created_at desc) where media_type in ('video/mp4','video/webm');

-- Interactive stories: polls and question boxes.
alter table public.community_stories
  add column if not exists interactive_type text not null default 'none',
  add column if not exists interactive_prompt text not null default '',
  add column if not exists interactive_options jsonb not null default '[]'::jsonb;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'community_stories_interactive_type_check') then
    alter table public.community_stories add constraint community_stories_interactive_type_check
      check (interactive_type in ('none','poll','question'));
  end if;
end $$;

create table if not exists public.community_story_responses (
  id uuid primary key default gen_random_uuid(),
  story_id uuid not null references public.community_stories(id) on delete cascade,
  viewer_id uuid not null references auth.users(id) on delete cascade,
  response_type text not null check (response_type in ('poll','question')),
  response_value text not null check (char_length(response_value) between 1 and 300),
  created_at timestamptz not null default now(),
  unique (story_id, viewer_id)
);
create index if not exists community_story_responses_story_idx
  on public.community_story_responses(story_id, created_at desc);

alter table public.community_story_responses enable row level security;
drop policy if exists "Story viewers respond once" on public.community_story_responses;
create policy "Story viewers respond once" on public.community_story_responses
for insert to authenticated with check (
  viewer_id = (select auth.uid()) and exists (
    select 1 from public.community_stories s
    where s.id = community_story_responses.story_id
      and s.expires_at > now() and s.author_id <> (select auth.uid())
      and s.interactive_type = community_story_responses.response_type
  )
);
drop policy if exists "Story owners and responders read responses" on public.community_story_responses;
create policy "Story owners and responders read responses" on public.community_story_responses
for select to authenticated using (
  viewer_id = (select auth.uid()) or exists (
    select 1 from public.community_stories s
    where s.id = community_story_responses.story_id and s.author_id = (select auth.uid())
  )
);
drop policy if exists "Users update own story response" on public.community_story_responses;
create policy "Users update own story response" on public.community_story_responses
for update to authenticated using (viewer_id = (select auth.uid()))
with check (viewer_id = (select auth.uid()));
grant select, insert, update on public.community_story_responses to authenticated;

-- Reels unique view records, used for deduplication and future creator insights.
create table if not exists public.community_reel_views (
  post_id uuid not null references public.community_posts(id) on delete cascade,
  viewer_id uuid not null references auth.users(id) on delete cascade,
  viewed_at timestamptz not null default now(),
  primary key (post_id, viewer_id)
);
create index if not exists community_reel_views_post_idx on public.community_reel_views(post_id);
alter table public.community_reel_views enable row level security;
drop policy if exists "Users record reel views" on public.community_reel_views;
create policy "Users record reel views" on public.community_reel_views
for insert to authenticated with check (
  viewer_id = (select auth.uid()) and exists (
    select 1 from public.community_posts p where p.id = community_reel_views.post_id
      and p.media_type in ('video/mp4','video/webm')
  )
);
drop policy if exists "Users update own reel views" on public.community_reel_views;
create policy "Users update own reel views" on public.community_reel_views
for update to authenticated using (viewer_id = (select auth.uid()))
with check (viewer_id = (select auth.uid()));
drop policy if exists "Reel owners and viewers read view records" on public.community_reel_views;
create policy "Reel owners and viewers read view records" on public.community_reel_views
for select to authenticated using (
  viewer_id = (select auth.uid()) or exists (
    select 1 from public.community_posts p
    where p.id = community_reel_views.post_id and p.author_id = (select auth.uid())
  )
);
grant select, insert, update on public.community_reel_views to authenticated;

-- Permit signed URLs for generated reel cover frames as well as original media.
drop policy if exists "Community media visible with post" on storage.objects;
create policy "Community media visible with post" on storage.objects
for select to authenticated using (
  bucket_id = 'community-media' and (
    exists (select 1 from public.community_posts cp
      where cp.media_path = objects.name or cp.cover_path = objects.name)
    or exists (select 1 from public.community_stories cs
      where cs.media_path = objects.name and cs.expires_at > now())
  )
);

grant usage on schema public to authenticated;

-- Poll results are exposed as aggregate counts only; individual votes remain private.
create or replace function public.get_community_story_poll_results(p_story_id uuid)
returns table(option_index integer, option_label text, vote_count bigint)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  story_owner uuid;
  options jsonb;
begin
  select s.author_id, s.interactive_options into story_owner, options
  from public.community_stories s
  where s.id = p_story_id and s.interactive_type = 'poll' and s.expires_at > now();
  if story_owner is null then raise exception 'Poll not found or expired'; end if;
  if story_owner <> auth.uid() and not exists (
    select 1 from public.community_story_responses r
    where r.story_id = p_story_id and r.viewer_id = auth.uid()
  ) then raise exception 'Vote in this poll to view results'; end if;
  return query
  select i::integer, options->>i, count(r.id)::bigint
  from generate_series(0, greatest(jsonb_array_length(options)-1,0)) as gs(i)
  left join public.community_story_responses r
    on r.story_id = p_story_id and r.response_type = 'poll' and r.response_value = gs.i::text
  group by gs.i
  order by gs.i;
end;
$$;
grant execute on function public.get_community_story_poll_results(uuid) to authenticated;
